// Builds accept_table_j1.json from the measurement logs.
// The expected strings are copied literally from those logs.
// Do not edit this file after it has run.
import { readFileSync, writeFileSync } from 'node:fs';

function load(path) {
  return readFileSync(path, 'utf8').split(/\r?\n/).filter(Boolean).map((line) => JSON.parse(line));
}

const probe = load('work/out/probe-j1.jsonl').filter((row) => row.id);
const reopen = load('work/out/probe-reopen-j1.jsonl').find((row) => row.id === 'reopen');
const bySession = new Map();
for (const row of probe) {
  if (!bySession.has(row.session)) bySession.set(row.session, []);
  bySession.get(row.session).push(row);
}
const control = new Map(bySession.get('control').map((row) => [row.id, row]));
const cand = new Map(bySession.get('cprobe').map((row) => [row.id, row]));
const p28c = new Map(bySession.get('p28-control').map((row) => [row.id, row]));
const p28d = new Map(bySession.get('p28-cprobe').map((row) => [row.id, row]));

function readback(controlRow, candidateRow, { cells = false, saves = false } = {}) {
  const source = controlRow || candidateRow;
  const body = {
    profile: candidateRow.profile,
    profileCached: candidateRow.profileCached,
    k90a1: source.invariant.k90a1,
    screen: source.screen,
    slotValue: source.slotValue,
    helpId: source.helpId,
    glyph: candidateRow.glyph,
    saves: saves ? source.saves : null,
    cells: cells ? source.invariant : null,
  };
  if (controlRow) {
    body.profileControl = controlRow.profile;
    body.profileCachedControl = controlRow.profileCached;
    body.glyphControl = controlRow.glyph;
    body.slotValue = controlRow.slotValue;
    body.helpId = controlRow.helpId;
    body.screen = controlRow.screen;
    body.k90a1 = controlRow.invariant.k90a1;
  }
  return body;
}

function stepFrom(row, controlRow, candidateRow, extra) {
  const shared = row.shared;
  const source = shared ? controlRow : candidateRow;
  return {
    id: row.id,
    lane: row.lane,
    shared,
    key: row.key,
    action: row.action,
    controlStep: shared ? row.id : null,
    expect: {
      title: source.title,
      highlight: source.highlight,
      invariant: true,
      readback: readback(shared ? controlRow : null, candidateRow, extra),
    },
  };
}

const steps = [];
for (const row of bySession.get('cprobe')) {
  const shared = row.shared;
  const controlRow = shared ? control.get(row.id) : null;
  if (shared && !controlRow) throw new Error('missing control row ' + row.id);
  const cells = row.id === 'baseline';
  const saves = row.id === 'save';
  steps.push(stepFrom(row, controlRow, cand.get(row.id), { cells, saves }));
}
for (const row of bySession.get('p28-control')) {
  const candidateRow = p28d.get(row.id);
  if (!candidateRow) throw new Error('missing page28 candidate ' + row.id);
  steps.push(stepFrom(row, p28c.get(row.id), candidateRow, { cells: row.id === 'p28-arm' }));
}

const baseline = control.get('baseline');
steps.push({
  id: 'store-compare',
  lane: 'store',
  shared: true,
  key: null,
  action: 'store-compare',
  controlStep: null,
  expect: {
    title: null,
    highlight: null,
    invariant: true,
    readback: { sameM: true, sameE: true, mBytes: 262144, eBytes: 196608, profile: null, profileCached: null, k90a1: baseline.invariant.k90a1, screen: null, slotValue: null, helpId: null, glyph: null, saves: null, cells: null },
  },
});
steps.push({
  id: 'overlay-compare',
  lane: 'store',
  shared: true,
  key: null,
  action: 'overlay-compare',
  controlStep: null,
  expect: {
    title: null,
    highlight: null,
    invariant: true,
    readback: { same: true, bytes: 32758, profile: null, profileCached: null, k90a1: baseline.invariant.k90a1, screen: null, slotValue: null, helpId: null, glyph: null, saves: null, cells: null },
  },
});
steps.push({
  id: 'reopen',
  lane: 'reopen',
  shared: false,
  key: null,
  action: 'reopen',
  controlStep: null,
  cellControlStep: 'baseline',
  expect: {
    title: reopen.title,
    highlight: reopen.highlight,
    invariant: true,
    readback: {
      profile: reopen.profile,
      profileCached: reopen.profileCached,
      k90a1: reopen.invariant.k90a1,
      screen: reopen.screen,
      slotValue: reopen.slotValue,
      helpId: reopen.helpId,
      glyph: reopen.glyph,
      saves: null,
      cells: reopen.invariant,
    },
  },
});

writeFileSync('work/scripts/accept_table_j1.json', JSON.stringify(steps, null, 2) + '\n');
console.log(JSON.stringify({ steps: steps.length, lanes: steps.reduce((m, s) => (m[s.lane] = (m[s.lane] || 0) + 1, m), {}) }));
